const b = $input.first().json.body || {};
const type = (b.type === 'series' || b.type === 'tv') ? 'series' : 'movie';
const id = String(b.imdbId || '').trim();
const title = String(b.title || '').trim();
const hasId = /^tt[0-9]+$/.test(id);
const url = hasId
  ? 'https://v3-cinemeta.strem.io/meta/' + type + '/' + id + '.json'
  : 'https://v3-cinemeta.strem.io/catalog/' + type + '/top/search=' + encodeURIComponent(title) + '.json';
const accents = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');
const q = title.toLowerCase().normalize('NFD').replace(accents, '').replace(/[^a-z0-9 ]+/g, ' ').trim().replace(/ +/g, '_');
return [{ json: { type, id: hasId ? id : '', title, year: String(b.year || ''), url, q, q0: q.charAt(0) || 'a', valid: hasId || title.length > 0 } }];

const p = $('Prepare').first().json;
const r = $input.first().json || {};
if (!p.valid) return [{ json: { found: false } }];
const accents = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(accents, '').replace(/[^a-z0-9]+/g, ' ').trim();
let meta = null;
if (r.meta && r.meta.id) meta = r.meta;
else if (Array.isArray(r.metas)) {
  const ty = norm(p.title);
  const y = parseInt(p.year, 10);
  const yr = m => parseInt(String(m.year || m.releaseInfo || '').slice(0, 4), 10);
  const c = r.metas;
  const near = m => !y || Math.abs(yr(m) - y) <= 1;
  meta = c.find(m => norm(m.name) === ty && near(m))
    || (y ? c.find(m => near(m) && (norm(m.name).indexOf(ty) === 0 || ty.indexOf(norm(m.name)) === 0)) : null);
}
if (!meta || !/^tt[0-9]+$/.test(String(meta.id))) return [{ json: { found: false } }];
const now = new Date().toISOString();
const item = {
  _id: meta.id,
  name: meta.name,
  type: p.type,
  poster: meta.poster || ('https://images.metahub.space/poster/medium/' + meta.id + '/img'),
  posterShape: 'poster',
  removed: false,
  temp: false,
  _ctime: now,
  _mtime: now,
  state: { lastWatched: now, timeWatched: 0, timeOffset: 0, overallTimeWatched: 0, timesWatched: 0, flaggedWatched: 0, duration: 0, video_id: meta.id, watched: '', noNotif: false, season: 0, episode: 0 },
  year: String(meta.year || meta.releaseInfo || '').slice(0, 4)
};
return [{ json: { found: true, id: meta.id, name: meta.name, changes: [item] } }];

const p = $('Prepare').first().json;
const r = $input.first().json || {};
const y = parseInt(p.year, 10);
if (!p.valid || !y || !p.q) return [{ json: { found: false } }];
const okType = p.type === 'series' ? ['tvSeries', 'tvMiniSeries'] : ['movie', 'tvMovie'];
const accents = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(accents, '').replace(/[^a-z0-9]+/g, ' ').trim();
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';
const get = async u => this.helpers.httpRequest({ url: u, json: true, headers: { 'User-Agent': UA } });
const pickImdb = list => (Array.isArray(list) ? list : []).find(x => /^tt[0-9]+$/.test(String(x.id)) && okType.indexOf(x.qid) >= 0 && x.y === y);
let hit = pickImdb(r.d);
let orig = '';
if (!hit) {
  // titre original (souvent anglais) via SensCritique, puis nouvelle recherche IMDb / Cinemeta
  try {
    const gq = 'query SearchAutocomplete($keywords: String!, $universe: String, $limit: Int) { searchAutocomplete(keywords: $keywords, universe: $universe, limit: $limit) { items { product { title originalTitle dateRelease dateReleaseOriginal yearOfProduction universe } } } }';
    const sc = await this.helpers.httpRequest({ method: 'POST', url: 'https://apollo.senscritique.com/', json: true, headers: { 'Content-Type': 'application/json', 'User-Agent': UA }, body: { operationName: 'SearchAutocomplete', variables: { keywords: p.title, universe: null, limit: 15 }, query: gq } });
    const items = (sc && sc.data && sc.data.searchAutocomplete && sc.data.searchAutocomplete.items) || [];
    const uni = p.type === 'series' ? 4 : 1;
    const yp = pr => parseInt(String(pr.yearOfProduction || pr.dateRelease || pr.dateReleaseOriginal || '').slice(0, 4), 10);
    const m = items.map(i => i && i.product).find(pr => pr && pr.universe === uni && pr.originalTitle && norm(pr.title) === norm(p.title) && Math.abs(yp(pr) - y) <= 1);
    if (m && norm(m.originalTitle) !== norm(p.title)) orig = m.originalTitle;
  } catch (e) {}
  if (orig) {
    const s = norm(orig).replace(/ +/g, '_');
    try { const r2 = await get('https://v3.sg.media-imdb.com/suggestion/' + (s.charAt(0) || 'a') + '/' + encodeURIComponent(s) + '.json'); hit = pickImdb(r2.d); } catch (e) {}
    if (!hit) {
      try {
        const r3 = await get('https://v3-cinemeta.strem.io/catalog/' + p.type + '/top/search=' + encodeURIComponent(orig) + '.json');
        const no = norm(orig);
        const yr = m => parseInt(String(m.year || m.releaseInfo || '').slice(0, 4), 10);
        const c = (r3.metas || []).find(m => /^tt[0-9]+$/.test(String(m.id)) && norm(m.name) === no && Math.abs(yr(m) - y) <= 1);
        if (c) hit = { id: c.id, l: c.name, y: yr(c), poster: c.poster };
      } catch (e) {}
    }
  }
}
if (!hit) return [{ json: { found: false, orig } }];
const now = new Date().toISOString();
const item = {
  _id: hit.id,
  name: hit.l,
  type: p.type,
  poster: hit.poster || ('https://images.metahub.space/poster/medium/' + hit.id + '/img'),
  posterShape: 'poster',
  removed: false,
  temp: false,
  _ctime: now,
  _mtime: now,
  state: { lastWatched: now, timeWatched: 0, timeOffset: 0, overallTimeWatched: 0, timesWatched: 0, flaggedWatched: 0, duration: 0, video_id: hit.id, watched: '', noNotif: false, season: 0, episode: 0 },
  year: String(hit.y)
};
return [{ json: { found: true, id: hit.id, name: hit.l, changes: [item] } }];

const put = $input.first().json || {};
let info = null;
try { const t = $('Pick IMDb').first().json; if (t && t.found) info = t; } catch (e) {}
if (!info) info = $('Pick Match').first().json;
return [{ json: { ok: !!(put.result && put.result.success === true), id: info.id, name: info.name } }];
